sections.code:
:root {
  --fundo: #F4F7F7;
  --texto: #19353d;
  --borda: #c5d5d8;
}
[data-theme="dark"] {
  --fundo: #0c171b;
  --texto: #f1f5f6;
  --borda: #445b63;
}
body { color: var(--texto); background: var(--fundo); }
button:focus-visible { outline: 3px solid #7563AD; }
@media (prefers-reduced-motion: reduce) {
  .card { transition: none; transform: none; }
}
